import { chromium } from 'playwright';

const BASE = 'http://127.0.0.1:3021';
const OUT = '/tmp/claude-0/-/a847f019-50a6-4b60-bcba-1133f2a3ca8a/scratchpad';
const VPS_ID = 'cmtot7pos0005hlf08v1zwbg1'; // db-primary.nxeon.cloud
const GAME_ID = 'cmtvcf5sj000asb634qakwex3'; // minecraft-22d1nt

async function toLightMode(page) {
  const theme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
  if (theme !== 'light') {
    const toggle = page.getByRole('switch', { name: /switch to light theme/i });
    if (await toggle.count() > 0) {
      await toggle.click();
      await page.waitForTimeout(300);
    }
  }
  return page.evaluate(() => document.documentElement.getAttribute('data-theme'));
}

async function getColors(page, selector) {
  return page.evaluate((sel) => {
    const root = getComputedStyle(document.documentElement);
    const bodyEl = document.body;
    const bodyStyle = getComputedStyle(bodyEl);
    let elInfo = null;
    if (sel) {
      const el = document.querySelector(sel);
      if (el) {
        const s = getComputedStyle(el);
        elInfo = { selector: sel, color: s.color, backgroundColor: s.backgroundColor, text: el.textContent?.slice(0,80) };
      }
    }
    return {
      dataTheme: document.documentElement.getAttribute('data-theme'),
      rootVars: {
        '--color-bg': root.getPropertyValue('--color-bg').trim(),
        '--color-bg-1': root.getPropertyValue('--color-bg-1').trim(),
        '--color-text': root.getPropertyValue('--color-text').trim(),
        '--color-fg': root.getPropertyValue('--color-fg').trim(),
      },
      bodyBg: bodyStyle.backgroundColor,
      bodyColor: bodyStyle.color,
      el: elInfo,
    };
  }, selector);
}

const browser = await chromium.launch();

// ===== Part 1: VPS + Game server detail pages =====
{
  const context = await browser.newContext({ storageState: '/opt/nxeon-v2/scratch-lightmode-verify/state.json' });
  const page = await context.newPage();

  console.log('\n--- VPS detail page ---');
  await page.goto(`${BASE}/dashboard/servers/${VPS_ID}`, { waitUntil: 'networkidle' });
  const vpsTheme = await toLightMode(page);
  await page.waitForTimeout(500);
  console.log('VPS data-theme after toggle:', vpsTheme);
  await page.screenshot({ path: `${OUT}/1-vps-detail-light.png`, fullPage: true });
  const vpsColors = await getColors(page, 'main, [class*="content"], h1');
  console.log('VPS colors:', JSON.stringify(vpsColors, null, 2));

  console.log('\n--- Game server detail page ---');
  await page.goto(`${BASE}/dashboard/servers/${GAME_ID}`, { waitUntil: 'networkidle' });
  // theme should persist (localStorage) but verify
  let gameTheme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
  console.log('Game server data-theme on load:', gameTheme);
  if (gameTheme !== 'light') {
    gameTheme = await toLightMode(page);
  }
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${OUT}/2-game-detail-light.png`, fullPage: true });
  const gameColors = await getColors(page, 'main, [class*="content"], h1');
  console.log('Game colors:', JSON.stringify(gameColors, null, 2));

  await context.close();
}

// ===== Part 2: Chat widget =====
{
  const context = await browser.newContext({ storageState: '/opt/nxeon-v2/scratch-lightmode-verify/state.json' });
  const page = await context.newPage();
  console.log('\n--- Chat widget ---');
  await page.goto(`${BASE}/dashboard/support`, { waitUntil: 'networkidle' });
  let theme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
  if (theme !== 'light') theme = await toLightMode(page);
  console.log('Support page data-theme:', theme);
  await page.waitForTimeout(500);

  // Look for a chat bubble / launcher button
  const chatSelectors = [
    'button[aria-label*="chat" i]',
    'button[aria-label*="support" i]',
    '[class*="chat-widget" i]',
    '[class*="chat-bubble" i]',
    '[class*="chatLauncher" i]',
    '[id*="chat" i]',
  ];
  let found = false;
  for (const sel of chatSelectors) {
    const loc = page.locator(sel);
    const count = await loc.count();
    if (count > 0) {
      console.log(`Found candidate chat elements with selector "${sel}": ${count}`);
      found = true;
    }
  }
  await page.screenshot({ path: `${OUT}/3a-support-page-light.png`, fullPage: true });

  // dump all buttons for inspection
  const allButtons = await page.$$eval('button, [role="button"]', els => els.map(e => ({
    aria: e.getAttribute('aria-label'),
    cls: (e.className || '').toString().slice(0,80),
    text: e.textContent?.slice(0,40),
  })).filter(b => b.aria || b.text));
  console.log('All buttons on support page (sample):', JSON.stringify(allButtons.slice(0, 40), null, 2));

  await context.close();
}

await browser.close();

