import { chromium } from 'playwright';
const BASE = 'http://127.0.0.1:3021';
const OUT = '/tmp/claude-0/-/a847f019-50a6-4b60-bcba-1133f2a3ca8a/scratchpad';
const browser = await chromium.launch();
const context = await browser.newContext({ storageState: '/opt/nxeon-v2/scratch-lightmode-verify/state.json' });
const page = await context.newPage();
await page.goto(`${BASE}/dashboard/support`, { waitUntil: 'networkidle' });

let theme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
if (theme !== 'light') {
  const toggle = page.getByRole('switch', { name: /switch to light theme/i });
  if (await toggle.count() > 0) { await toggle.click(); await page.waitForTimeout(300); }
}
theme = await page.evaluate(() => document.documentElement.getAttribute('data-theme'));
console.log('theme:', theme);

// dismiss cookie banner if present so it doesn't obstruct
const gotIt = page.getByRole('button', { name: 'Got it' });
if (await gotIt.count() > 0) { await gotIt.click().catch(()=>{}); await page.waitForTimeout(200); }

await page.getByRole('button', { name: 'Open chat' }).click();
await page.waitForTimeout(800);
await page.screenshot({ path: `${OUT}/3-chat-widget-open-light.png`, fullPage: true });

const info = await page.evaluate(() => {
  // Try to find the chat panel container - look for elements that appeared, likely fixed position near bottom right
  const candidates = Array.from(document.querySelectorAll('div')).filter(d => {
    const r = d.getBoundingClientRect();
    const s = getComputedStyle(d);
    return s.position === 'fixed' && r.width > 250 && r.height > 300;
  });
  return candidates.map(el => {
    const s = getComputedStyle(el);
    return {
      cls: el.className.toString().slice(0,150),
      bg: s.backgroundColor,
      color: s.color,
      rect: el.getBoundingClientRect().toJSON ? {w: el.getBoundingClientRect().width, h: el.getBoundingClientRect().height} : null,
    };
  });
});
console.log('Fixed large panels:', JSON.stringify(info, null, 2));

// grab text nodes within the widget and their computed colors
const textInfo = await page.evaluate(() => {
  const panels = Array.from(document.querySelectorAll('div')).filter(d => {
    const r = d.getBoundingClientRect();
    const s = getComputedStyle(d);
    return s.position === 'fixed' && r.width > 250 && r.height > 300;
  });
  if (panels.length === 0) return null;
  const panel = panels[0];
  const walker = document.createTreeWalker(panel, NodeFilter.SHOW_ELEMENT);
  const out = [];
  let node = walker.currentNode;
  let count = 0;
  while (node && count < 15) {
    if (node.textContent && node.textContent.trim().length > 0 && node.children.length === 0) {
      const s = getComputedStyle(node);
      out.push({ tag: node.tagName, text: node.textContent.trim().slice(0,50), color: s.color, bg: s.backgroundColor });
      count++;
    }
    node = walker.nextNode();
  }
  return out;
});
console.log('Text elements inside chat panel:', JSON.stringify(textInfo, null, 2));

await browser.close();
EOF
